package com.jono.app;
import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import com.google.firebase.auth.FirebaseAuth; import com.google.firebase.firestore.FirebaseFirestore; import java.util.HashMap; import java.util.Map;
public class RegisterActivity extends AppCompatActivity { EditText name,email,password; public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,64,32,32); TextView t=new TextView(this);t.setText("Jono\nCreate account");t.setTextSize(28);name=new EditText(this);name.setHint("Name");email=new EditText(this);email.setHint("Email");password=new EditText(this);password.setHint("Password");password.setInputType(129);Button x=new Button(this);x.setText("Register");l.addView(t);l.addView(name);l.addView(email);l.addView(password);l.addView(x);setContentView(l);x.setOnClickListener(v->FirebaseAuth.getInstance().createUserWithEmailAndPassword(email.getText().toString(),password.getText().toString()).addOnCompleteListener(q->{if(q.isSuccessful()){String uid=FirebaseAuth.getInstance().getCurrentUser().getUid();Map<String,Object> u=new HashMap<>();u.put("uid",uid);u.put("displayName",name.getText().toString());u.put("email",email.getText().toString());u.put("role","user");FirebaseFirestore.getInstance().collection("users").document(uid).set(u);finish();}else Toast.makeText(this,"Registration failed",Toast.LENGTH_SHORT).show();}));}}
